    List<Integer> expected = Arrays.asList(-100, -50, 0, 50, 100);
    expected.forEach(i -> {
        try {
            db.write(createCustomType1(i));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    try (KVStoreIterator<CustomType1> iterator = db.view(CustomType1.class).index("int").closeableIterator()) {
        List<Integer> results = StreamSupport.stream(Spliterators.spliteratorUnknownSize(iterator, 0), false).map(e -> e.num).collect(Collectors.toList());
        assertEquals(expected, results);
    }
}

@Test
public void testCloseLevelDBIterator() throws Exception {
    // SPARK-31929: test when LevelDB.close() is called, related LevelDBIterators
    // are closed. And files opened by iterators are also closed.
    File dbPathForCloseTest = File.createTempFile("test_db_close.", ".ldb");
    dbPathForCloseTest.delete();
    LevelDB dbForCloseTest = new LevelDB(dbPathForCloseTest);
    for (int i = 0; i < 8192; i++) {
        dbForCloseTest.write(createCustomType1(i));
    }
    String key = dbForCloseTest.view(CustomType1.class).iterator().next().key;
    assertEquals("key0", key);
    Iterator<CustomType1> it0 = dbForCloseTest.view(CustomType1.class).max(1).iterator();
    while (it0.hasNext()) {
        it0.next();
    }
    System.gc();
    Iterator<CustomType1> it1 = dbForCloseTest.view(CustomType1.class).iterator();
    assertEquals("key0", it1.next().key);
    try (KVStoreIterator<CustomType1> it2 = dbForCloseTest.view(CustomType1.class).closeableIterator()) {
        assertEquals("key0", it2.next().key);
    }
