        JavaUtils.closeQuietly(server);
        Thread.sleep(1000);
        IOException exception = Assertions.assertThrows(IOException.class, () -> factory.createClient(TestUtils.getLocalHost(), unreachablePort, true));
        assertNotEquals(exception.getCause(), null);
