    Semaphore closed = new Semaphore(0);
    pushResolver = new RemoteBlockPushResolver(conf, null) {

        @Override
        void closeAndDeletePartitionsIfNeeded(AppShuffleInfo appShuffleInfo, boolean cleanupLocalDirs) {
