    registerExecutor(testApp, prepareLocalDirs(attempt1LocalDirs, MERGE_DIRECTORY + "_" + ATTEMPT_ID_1), MERGE_DIRECTORY_META_1);
    ByteBuffer[] blocks = new ByteBuffer[] { ByteBuffer.wrap(new byte[4]), ByteBuffer.wrap(new byte[5]) };
    StreamCallbackWithID stream1 = pushResolver.receiveBlockDataAsStream(new PushBlockStream(testApp, 1, 0, 0, 0, 0, 0));
    for (ByteBuffer block : blocks) {
        stream1.onData(stream1.getID(), block);
    }
    stream1.onComplete(stream1.getID());
    RemoteBlockPushResolver.AppShuffleInfo appShuffleInfo = pushResolver.validateAndGetAppShuffleInfo(testApp);
    RemoteBlockPushResolver.AppShuffleMergePartitionsInfo partitions = appShuffleInfo.getShuffles().get(0);
    for (RemoteBlockPushResolver.AppShufflePartitionInfo partitionInfo : partitions.getShuffleMergePartitions().values()) {
        assertTrue(partitionInfo.getDataChannel().isOpen());
        assertTrue(partitionInfo.getMetaFile().getChannel().isOpen());
        assertTrue(partitionInfo.getIndexFile().getChannel().isOpen());
    }
    Path[] attempt2LocalDirs = createLocalDirs(2);
