    assertInitCap("FIDELİO", UNICODE_CI, "Fideli\u0307o");
    // Surrogate pairs.
    assertInitCap("a🙃B🙃c", UTF8_BINARY, "A🙃b🙃c");
    assertInitCap("a🙃B🙃c", UTF8_LCASE, "A🙃B🙃C");
    assertInitCap("a🙃B🙃c", UNICODE, "A🙃B🙃C");
