    UTF8String[] negativeAndZeroLimitCase = new UTF8String[] { fromString("ab"), fromString("def"), fromString("ghi"), fromString("") };
    assertArrayEquals(negativeAndZeroLimitCase, fromString("ab,def,ghi,").split(fromString(","), 0));
    assertArrayEquals(negativeAndZeroLimitCase, fromString("ab,def,ghi,").split(fromString(","), -1));
    assertArrayEquals(new UTF8String[] { fromString("ab"), fromString("def,ghi,") }, fromString("ab,def,ghi,").split(fromString(","), 2));
    // Split with empty pattern ignores trailing empty spaces.
    assertArrayEquals(new UTF8String[] { fromString("a"), fromString("b") }, fromString("ab").split(fromString(""), 0));
    assertArrayEquals(new UTF8String[] { fromString("a"), fromString("b") }, fromString("ab").split(fromString(""), -1));
    assertArrayEquals(new UTF8String[] { fromString("a"), fromString("b") }, fromString("ab").split(fromString(""), 2));
    assertArrayEquals(new UTF8String[] { fromString("a"), fromString("b") }, fromString("ab").split(fromString(""), 100));
    assertArrayEquals(new UTF8String[] { fromString("ab") }, fromString("ab").split(fromString(""), 1));
    assertArrayEquals(new UTF8String[] { fromString("") }, fromString("").split(fromString(""), 0));
}

