@Test
public void skipWrongFirstByte() {
    int[] wrongFirstBytes = { // Skip Continuation bytes
    0x80, // Skip Continuation bytes
    0x9F, // Skip Continuation bytes
    0xBF, // 0xC0..0xC1 - disallowed in UTF-8
    0xC0, // 0xC0..0xC1 - disallowed in UTF-8
    0xC2, // 0xF5..0xFF - disallowed in UTF-8
    0xF5, 0xF6, 0xF7, 0xF8, 0xF9, 0xFA, 0xFB, 0xFC, 0xFD, 0xFE, 0xFF };
    byte[] c = new byte[1];
    for (int wrongFirstByte : wrongFirstBytes) {
        c[0] = (byte) wrongFirstByte;
        assertEquals(1, fromBytes(c).numChars());
    }
}

