public void testConsumerStrategyConstructors() {
    final String topic1 = "topic1";
    final Pattern pat = Pattern.compile("top.*");
    final Collection<String> topics = Arrays.asList(topic1);
    final scala.collection.Iterable<String> sTopics = CollectionConverters.asScala(topics);
    final TopicPartition tp1 = new TopicPartition(topic1, 0);
    final TopicPartition tp2 = new TopicPartition(topic1, 1);
    final Collection<TopicPartition> parts = Arrays.asList(tp1, tp2);
    final scala.collection.Iterable<TopicPartition> sParts = CollectionConverters.asScala(parts);
    final Map<String, Object> kafkaParams = new HashMap<>();
    kafkaParams.put("bootstrap.servers", "not used");
    final scala.collection.Map<String, Object> sKafkaParams = CollectionConverters.asScala(kafkaParams);
    final Map<TopicPartition, Long> offsets = new HashMap<>();
    offsets.put(tp1, 23L);
    final Map<TopicPartition, Object> dummyOffsets = new HashMap<>();
    dummyOffsets.putAll(offsets);
    final scala.collection.Map<TopicPartition, Object> sOffsets = CollectionConverters.asScala(dummyOffsets);
    final ConsumerStrategy<String, String> sub1 = ConsumerStrategies.Subscribe(sTopics, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> sub2 = ConsumerStrategies.Subscribe(sTopics, sKafkaParams);
    final ConsumerStrategy<String, String> sub3 = ConsumerStrategies.Subscribe(topics, kafkaParams, offsets);
    final ConsumerStrategy<String, String> sub4 = ConsumerStrategies.Subscribe(topics, kafkaParams);
    Assertions.assertEquals(sub1.executorKafkaParams().get("bootstrap.servers"), sub3.executorKafkaParams().get("bootstrap.servers"));
    final ConsumerStrategy<String, String> psub1 = ConsumerStrategies.SubscribePattern(pat, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> psub2 = ConsumerStrategies.SubscribePattern(pat, sKafkaParams);
    final ConsumerStrategy<String, String> psub3 = ConsumerStrategies.SubscribePattern(pat, kafkaParams, offsets);
    final ConsumerStrategy<String, String> psub4 = ConsumerStrategies.SubscribePattern(pat, kafkaParams);
    Assertions.assertEquals(psub1.executorKafkaParams().get("bootstrap.servers"), psub3.executorKafkaParams().get("bootstrap.servers"));
    final ConsumerStrategy<String, String> asn1 = ConsumerStrategies.Assign(sParts, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> asn2 = ConsumerStrategies.Assign(sParts, sKafkaParams);
    final ConsumerStrategy<String, String> asn3 = ConsumerStrategies.Assign(parts, kafkaParams, offsets);
    final ConsumerStrategy<String, String> asn4 = ConsumerStrategies.Assign(parts, kafkaParams);
    Assertions.assertEquals(asn1.executorKafkaParams().get("bootstrap.servers"), asn3.executorKafkaParams().get("bootstrap.servers"));
}

@Test
public void testKafkaStream() throws InterruptedException {
    final String topic1 = "topic1";
    final String topic2 = "topic2";
    // hold a reference to the current offset ranges, so it can be used downstream
    final AtomicReference<OffsetRange[]> offsetRanges = new AtomicReference<>();
    String[] topic1data = createTopicAndSendData(topic1);
    String[] topic2data = createTopicAndSendData(topic2);
    Set<String> sent = new HashSet<>();
    sent.addAll(Arrays.asList(topic1data));
    sent.addAll(Arrays.asList(topic2data));
    Random random = new Random();
    final Map<String, Object> kafkaParams = new HashMap<>();
    kafkaParams.put("bootstrap.servers", kafkaTestUtils.brokerAddress());
    kafkaParams.put("key.deserializer", StringDeserializer.class);
    kafkaParams.put("value.deserializer", StringDeserializer.class);
    kafkaParams.put("auto.offset.reset", "earliest");
    kafkaParams.put("group.id", "java-test-consumer-" + random.nextInt() + "-" + System.currentTimeMillis());
    JavaInputDStream<ConsumerRecord<String, String>> istream1 = KafkaUtils.createDirectStream(ssc, LocationStrategies.PreferConsistent(), ConsumerStrategies.Subscribe(Arrays.asList(topic1), kafkaParams));
    JavaDStream<String> stream1 = istream1.transform(// Make sure you can get offset ranges from the rdd
    (Function<JavaRDD<ConsumerRecord<String, String>>, JavaRDD<ConsumerRecord<String, String>>>) rdd -> {
        OffsetRange[] offsets = ((HasOffsetRanges) rdd.rdd()).offsetRanges();
        offsetRanges.set(offsets);
        Assertions.assertEquals(topic1, offsets[0].topic());
        return rdd;
    }).map((Function<ConsumerRecord<String, String>, String>) ConsumerRecord::value);
    final Map<String, Object> kafkaParams2 = new HashMap<>(kafkaParams);
    kafkaParams2.put("group.id", "java-test-consumer-" + random.nextInt() + "-" + System.currentTimeMillis());
    JavaInputDStream<ConsumerRecord<String, String>> istream2 = KafkaUtils.createDirectStream(ssc, LocationStrategies.PreferConsistent(), ConsumerStrategies.Subscribe(Arrays.asList(topic2), kafkaParams2));
    JavaDStream<String> stream2 = istream2.transform(// Make sure you can get offset ranges from the rdd
    (Function<JavaRDD<ConsumerRecord<String, String>>, JavaRDD<ConsumerRecord<String, String>>>) rdd -> {
        OffsetRange[] offsets = ((HasOffsetRanges) rdd.rdd()).offsetRanges();
        offsetRanges.set(offsets);
        Assertions.assertEquals(topic2, offsets[0].topic());
        return rdd;
    }).map((Function<ConsumerRecord<String, String>, String>) ConsumerRecord::value);
    JavaDStream<String> unifiedStream = stream1.union(stream2);
    final Set<String> result = Collections.synchronizedSet(new HashSet<>());
    unifiedStream.foreachRDD((VoidFunction<JavaRDD<String>>) rdd -> result.addAll(rdd.collect()));
    ssc.start();
    long startTime = System.currentTimeMillis();
    boolean matches = false;
    while (!matches && System.currentTimeMillis() - startTime < 20000) {
        matches = sent.size() == result.size();
        Thread.sleep(50);
    }
    Assertions.assertEquals(sent, result);
    ssc.stop();
}

