        Assertions.assertArrayEquals(keyData, getByteArray(loc.getKeyBase(), loc.getKeyOffset(), recordLengthBytes));
        Assertions.assertArrayEquals(valueData, getByteArray(loc.getValueBase(), loc.getValueOffset(), recordLengthBytes));
        // After calling lookup() the location should still point to the correct data.
        Assertions.assertTrue(map.lookup(keyData, Platform.BYTE_ARRAY_OFFSET, recordLengthBytes).isDefined());
        Assertions.assertEquals(recordLengthBytes, loc.getKeyLength());
        Assertions.assertEquals(recordLengthBytes, loc.getValueLength());
        Assertions.assertArrayEquals(keyData, getByteArray(loc.getKeyBase(), loc.getKeyOffset(), recordLengthBytes));
        Assertions.assertArrayEquals(valueData, getByteArray(loc.getValueBase(), loc.getValueOffset(), recordLengthBytes));
    } finally {
        map.free();
    }
}

