@Test
public void iteratingOverDataPagesWithWastedSpace() throws Exception {
    final int NUM_ENTRIES = 1000 * 1000;
    final int KEY_LENGTH = 24;
    final int VALUE_LENGTH = 40;
    final BytesToBytesMap map = new BytesToBytesMap(taskMemoryManager, NUM_ENTRIES, PAGE_SIZE_BYTES);
    // Each record will take 8 + 24 + 40 = 72 bytes of space in the data page. Our 64-megabyte
    // pages won't be evenly-divisible by records of this size, which will cause us to waste some
    // space at the end of the page. This is necessary in order for us to take the end-of-record
    // handling branch in iterator().
    try {
        for (int i = 0; i < NUM_ENTRIES; i++) {
            // 3 * 8 = 24 bytes
            final long[] key = new long[] { i, i, i };
            // 5 * 8 = 40 bytes
            final long[] value = new long[] { i, i, i, i, i };
            final BytesToBytesMap.Location loc = map.lookup(key, Platform.LONG_ARRAY_OFFSET, KEY_LENGTH);
            Assertions.assertFalse(loc.isDefined());
            Assertions.assertTrue(loc.append(key, Platform.LONG_ARRAY_OFFSET, KEY_LENGTH, value, Platform.LONG_ARRAY_OFFSET, VALUE_LENGTH));
        }
        Assertions.assertEquals(2, map.getNumDataPages());
        final java.util.BitSet valuesSeen = new java.util.BitSet(NUM_ENTRIES);
        final Iterator<BytesToBytesMap.Location> iter = map.iterator();
        final long[] key = new long[KEY_LENGTH / 8];
        final long[] value = new long[VALUE_LENGTH / 8];
        while (iter.hasNext()) {
            final BytesToBytesMap.Location loc = iter.next();
            Assertions.assertTrue(loc.isDefined());
            Assertions.assertEquals(KEY_LENGTH, loc.getKeyLength());
            Assertions.assertEquals(VALUE_LENGTH, loc.getValueLength());
            Platform.copyMemory(loc.getKeyBase(), loc.getKeyOffset(), key, Platform.LONG_ARRAY_OFFSET, KEY_LENGTH);
            Platform.copyMemory(loc.getValueBase(), loc.getValueOffset(), value, Platform.LONG_ARRAY_OFFSET, VALUE_LENGTH);
            for (long j : key) {
                Assertions.assertEquals(key[0], j);
            }
            for (long j : value) {
                Assertions.assertEquals(key[0], j);
            }
            valuesSeen.set((int) key[0]);
        }
        Assertions.assertEquals(NUM_ENTRIES, valuesSeen.cardinality());
    } finally {
        map.free();
    }
}

@Test
public void randomizedStressTest() {
    final int size = 32768;
    // Java arrays' hashCodes() aren't based on the arrays' contents, so we need to wrap arrays
    // into ByteBuffers in order to use them as keys here.
    final Map<ByteBuffer, byte[]> expected = new HashMap<>();
    final BytesToBytesMap map = new BytesToBytesMap(taskMemoryManager, size, PAGE_SIZE_BYTES);
    try {
        // Fill the map to 90% full so that we can trigger probing
        for (int i = 0; i < size * 0.9; i++) {
            final byte[] key = getRandomByteArray(rand.nextInt(256) + 1);
            final byte[] value = getRandomByteArray(rand.nextInt(256) + 1);
            if (!expected.containsKey(ByteBuffer.wrap(key))) {
                expected.put(ByteBuffer.wrap(key), value);
                final BytesToBytesMap.Location loc = map.lookup(key, Platform.BYTE_ARRAY_OFFSET, key.length);
                Assertions.assertFalse(loc.isDefined());
                Assertions.assertTrue(loc.append(key, Platform.BYTE_ARRAY_OFFSET, key.length, value, Platform.BYTE_ARRAY_OFFSET, value.length));
                // After calling putNewKey, the following should be true, even before calling
                // lookup():
                Assertions.assertTrue(loc.isDefined());
                Assertions.assertEquals(key.length, loc.getKeyLength());
                Assertions.assertEquals(value.length, loc.getValueLength());
                Assertions.assertTrue(arrayEquals(key, loc.getKeyBase(), loc.getKeyOffset(), key.length));
                Assertions.assertTrue(arrayEquals(value, loc.getValueBase(), loc.getValueOffset(), value.length));
            }
        }
        for (Map.Entry<ByteBuffer, byte[]> entry : expected.entrySet()) {
            final byte[] key = JavaUtils.bufferToArray(entry.getKey());
            final byte[] value = entry.getValue();
            final BytesToBytesMap.Location loc = map.lookup(key, Platform.BYTE_ARRAY_OFFSET, key.length);
            Assertions.assertTrue(loc.isDefined());
            Assertions.assertTrue(arrayEquals(key, loc.getKeyBase(), loc.getKeyOffset(), loc.getKeyLength()));
            Assertions.assertTrue(arrayEquals(value, loc.getValueBase(), loc.getValueOffset(), loc.getValueLength()));
        }
    } finally {
        map.free();
    }
}

