@Test
public void testPCA() {
    List<Vector> points = Arrays.asList(Vectors.sparse(5, new int[] { 1, 3 }, new double[] { 1.0, 7.0 }), Vectors.dense(2.0, 0.0, 3.0, 4.0, 5.0), Vectors.dense(4.0, 0.0, 0.0, 6.0, 7.0));
    JavaRDD<Vector> dataRDD = jsc.parallelize(points, 2);
    RowMatrix mat = new RowMatrix(dataRDD.map((Vector vector) -> org.apache.spark.mllib.linalg.Vectors.fromML(vector)).rdd());
    Matrix pc = mat.computePrincipalComponents(3);
    mat.multiply(pc).rows().toJavaRDD();
    JavaRDD<Vector> expected = mat.multiply(pc).rows().toJavaRDD().map(org.apache.spark.mllib.linalg.Vector::asML);
    JavaRDD<VectorPair> featuresExpected = dataRDD.zip(expected).map(pair -> {
        VectorPair featuresExpected1 = new VectorPair();
        featuresExpected1.setFeatures(pair._1());
        featuresExpected1.setExpected(pair._2());
        return featuresExpected1;
    });
    Dataset<Row> df = spark.createDataFrame(featuresExpected, VectorPair.class);
    PCAModel pca = new PCA().setInputCol("features").setOutputCol("pca_features").setK(3).fit(df);
    List<Row> result = pca.transform(df).select("pca_features", "expected").toJavaRDD().collect();
    for (Row r : result) {
        Vector calculatedVector = (Vector) r.get(0);
        Vector expectedVector = (Vector) r.get(1);
        for (int i = 0; i < calculatedVector.size(); i++) {
            Assertions.assertEquals(calculatedVector.apply(i), expectedVector.apply(i), 1.0e-8);
        }
    }
}

