@Test
public void testBasicFunction() {
    List<List<String>> inputData = Arrays.asList(Collections.emptyList(), Arrays.asList("a"), Arrays.asList("a", "b"), Arrays.asList("a", "b", "c"), Arrays.asList("a", "b"), Arrays.asList("a"), Collections.emptyList());
    List<Set<Integer>> outputData = Arrays.asList(Collections.emptySet(), Set.of(1), Set.of(2, 1), Set.of(3, 2, 1), Set.of(4, 3), Set.of(5), Collections.emptySet());
    @SuppressWarnings("unchecked")
    List<Set<Tuple2<String, Integer>>> stateData = Arrays.asList(Collections.emptySet(), Set.of(new Tuple2<>("a", 1)), Set.of(new Tuple2<>("a", 2), new Tuple2<>("b", 1)), Set.of(new Tuple2<>("a", 3), new Tuple2<>("b", 2), new Tuple2<>("c", 1)), Set.of(new Tuple2<>("a", 4), new Tuple2<>("b", 3), new Tuple2<>("c", 1)), Set.of(new Tuple2<>("a", 5), new Tuple2<>("b", 3), new Tuple2<>("c", 1)), Set.of(new Tuple2<>("a", 5), new Tuple2<>("b", 3), new Tuple2<>("c", 1)));
    Function3<String, Optional<Integer>, State<Integer>, Integer> mappingFunc = (key, value, state) -> {
        int sum = value.orElse(0) + (state.exists() ? state.get() : 0);
        state.update(sum);
        return sum;
    };
    testOperation(inputData, StateSpec.function(mappingFunc), outputData, stateData);
}

@Test
public void testReceiver() throws InterruptedException {
    TestServer server = new TestServer(0);
    server.start();
    AtomicLong dataCounter = new AtomicLong(0);
    try {
        JavaStreamingContext ssc = new JavaStreamingContext("local[2]", "test", new Duration(200));
        JavaReceiverInputDStream<String> input = ssc.receiverStream(new JavaSocketReceiver("localhost", server.port()));
        JavaDStream<String> mapped = input.map((Function<String, String>) v1 -> v1 + ".");
        mapped.foreachRDD((VoidFunction<JavaRDD<String>>) rdd -> {
            long count = rdd.count();
            dataCounter.addAndGet(count);
        });
        ssc.start();
        long startTimeNs = System.nanoTime();
        long timeout = TimeUnit.SECONDS.toNanos(10);
        Thread.sleep(200);
        for (int i = 0; i < 6; i++) {
            // \n to make sure these are separate lines
            server.send(i + "\n");
            Thread.sleep(100);
        }
        while (dataCounter.get() == 0 && System.nanoTime() - startTimeNs < timeout) {
            Thread.sleep(100);
        }
        ssc.stop();
        Assertions.assertTrue(dataCounter.get() > 0);
    } finally {
        server.stop();
    }
}

