@Test
public void testCoGroup() {
    List<List<Tuple2<String, String>>> stringStringKVStream1 = Arrays.asList(Arrays.asList(new Tuple2<>("california", "dodgers"), new Tuple2<>("new york", "yankees")), Arrays.asList(new Tuple2<>("california", "sharks"), new Tuple2<>("new york", "rangers")));
    List<List<Tuple2<String, String>>> stringStringKVStream2 = Arrays.asList(Arrays.asList(new Tuple2<>("california", "giants"), new Tuple2<>("new york", "mets")), Arrays.asList(new Tuple2<>("california", "ducks"), new Tuple2<>("new york", "islanders")));
    List<List<Tuple2<String, Tuple2<List<String>, List<String>>>>> expected = Arrays.asList(Arrays.asList(new Tuple2<>("california", new Tuple2<>(Arrays.asList("dodgers"), Arrays.asList("giants"))), new Tuple2<>("new york", new Tuple2<>(Arrays.asList("yankees"), Arrays.asList("mets")))), Arrays.asList(new Tuple2<>("california", new Tuple2<>(Arrays.asList("sharks"), Arrays.asList("ducks"))), new Tuple2<>("new york", new Tuple2<>(Arrays.asList("rangers"), Arrays.asList("islanders")))));
    JavaDStream<Tuple2<String, String>> stream1 = JavaTestUtils.attachTestInputStream(ssc, stringStringKVStream1, 1);
    JavaPairDStream<String, String> pairStream1 = JavaPairDStream.fromJavaDStream(stream1);
    JavaDStream<Tuple2<String, String>> stream2 = JavaTestUtils.attachTestInputStream(ssc, stringStringKVStream2, 1);
    JavaPairDStream<String, String> pairStream2 = JavaPairDStream.fromJavaDStream(stream2);
    JavaPairDStream<String, Tuple2<Iterable<String>, Iterable<String>>> grouped = pairStream1.cogroup(pairStream2);
    JavaTestUtils.attachTestOutputStream(grouped);
    List<List<Tuple2<String, Tuple2<Iterable<String>, Iterable<String>>>>> result = JavaTestUtils.runStreams(ssc, 2, 2);
    Assertions.assertEquals(expected.size(), result.size());
    Iterator<List<Tuple2<String, Tuple2<Iterable<String>, Iterable<String>>>>> resultItr = result.iterator();
    Iterator<List<Tuple2<String, Tuple2<List<String>, List<String>>>>> expectedItr = expected.iterator();
    while (resultItr.hasNext() && expectedItr.hasNext()) {
        Iterator<Tuple2<String, Tuple2<Iterable<String>, Iterable<String>>>> resultElements = resultItr.next().iterator();
        Iterator<Tuple2<String, Tuple2<List<String>, List<String>>>> expectedElements = expectedItr.next().iterator();
        while (resultElements.hasNext() && expectedElements.hasNext()) {
            Tuple2<String, Tuple2<Iterable<String>, Iterable<String>>> resultElement = resultElements.next();
            Tuple2<String, Tuple2<List<String>, List<String>>> expectedElement = expectedElements.next();
            Assertions.assertEquals(expectedElement._1(), resultElement._1());
            equalIterable(expectedElement._2()._1(), resultElement._2()._1());
            equalIterable(expectedElement._2()._2(), resultElement._2()._2());
        }
        Assertions.assertEquals(resultElements.hasNext(), expectedElements.hasNext());
    }
}

